CREATE OR ALTER PROCEDURE [dbo].[uspPackagingLedger_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @DeliveryLocationId UNIQUEIDENTIFIER = NULL
	, @OrderId UNIQUEIDENTIFIER = NULL
	, @DeliveryRouteId UNIQUEIDENTIFIER = NULL
	, @TransactionType NVARCHAR(MAX) = NULL
	, @PackagingType NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, j1.[DisplayName] AS [CustomerName]
			, t.[DeliveryLocationId]
			, t.[OrderId]
			, j2.[OrderNo] AS [OrderName]
			, t.[DeliveryRouteId]
			, j3.[Name] AS [DeliveryRouteName]
			, t.[TransactionType]
			, t.[PackagingType]
			, t.[Quantity]
			, t.[TransactionAt]
			, t.[ReferenceNo]
			, t.[ConditionCode]
			, t.[RecordedBy]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[PackagingLedger] AS t
		LEFT JOIN [dbo].[Customer] AS j1 ON j1.[Id] = t.[CustomerId]
		LEFT JOIN [dbo].[Order] AS j2 ON j2.[Id] = t.[OrderId]
		LEFT JOIN [dbo].[DeliveryRoute] AS j3 ON j3.[Id] = t.[DeliveryRouteId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ReferenceNo] LIKE CONCAT('%', @SearchText, '%') OR t.[ConditionCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (@DeliveryLocationId IS NULL OR t.[DeliveryLocationId] = @DeliveryLocationId)
			AND (@OrderId IS NULL OR t.[OrderId] = @OrderId)
			AND (@DeliveryRouteId IS NULL OR t.[DeliveryRouteId] = @DeliveryRouteId)
			AND (ISNULL(@TransactionType, '') = '' OR t.[TransactionType] = @TransactionType)
			AND (ISNULL(@PackagingType, '') = '' OR t.[PackagingType] = @PackagingType)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerName' THEN r.[CustomerName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerName' THEN r.[CustomerName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryLocationId' THEN r.[DeliveryLocationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryLocationId' THEN r.[DeliveryLocationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderId' THEN r.[OrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderId' THEN r.[OrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'orderName' THEN r.[OrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'orderName' THEN r.[OrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteId' THEN r.[DeliveryRouteId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'deliveryRouteName' THEN r.[DeliveryRouteName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'transactionType' THEN r.[TransactionType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'transactionType' THEN r.[TransactionType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'packagingType' THEN r.[PackagingType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'packagingType' THEN r.[PackagingType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'quantity' THEN r.[Quantity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'quantity' THEN r.[Quantity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'transactionAt' THEN r.[TransactionAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'transactionAt' THEN r.[TransactionAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'referenceNo' THEN r.[ReferenceNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'referenceNo' THEN r.[ReferenceNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'conditionCode' THEN r.[ConditionCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'conditionCode' THEN r.[ConditionCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'recordedBy' THEN r.[RecordedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
